import 'package:formularium/features/localization/localizable_interface.dart';
import 'package:freezed_annotation/freezed_annotation.dart';
import 'package:reef_fp/result.dart';

part 'task_edit_model.freezed.dart';
part 'task_edit_model.g.dart';

/// The page's domain model: pure, immutable, serializable (hibernation
/// contract). Fallsible modifications return `Result<E, Model>`; the model
/// never carries async/error state — that lives on the viewmodel.
///
/// Generated by freezed: `==`, `hashCode`, `toString`, `copyWith` and the
/// JSON codec come for free. `copyWith` is fine for mechanical field diffs;
/// **invariant-bearing changes go through the named methods** below, which
/// are the model's mutation language and the single place its rules live.
@freezed
abstract class TaskEditModel with _$TaskEditModel {
  // Required so the hand-written methods below can read the generated fields.
  const TaskEditModel._();

  const factory TaskEditModel({
    @Default('') String title,
    DateTime? dueDate,
  }) = _TaskEditModel;

  factory TaskEditModel.fromJson(Map<String, dynamic> json) =>
      _$TaskEditModelFromJson(json);

  /// Infallible change: returns the modified model.
  TaskEditModel withTitle(String value) =>
      TaskEditModel(title: value, dueDate: dueDate);

  /// Fallible change: the domain invariant lives here and is **delegated to**
  /// by the formularium field validator (single source of truth). `null`
  /// clears the due date. Day-granularity comparison (time of day ignored).
  Result<TaskError, TaskEditModel> withDueDate(DateTime? date) {
    if (date == null) {
      return Ok(TaskEditModel(title: title));
    }
    final now = DateTime.now();
    final today = DateTime(now.year, now.month, now.day);
    final day = DateTime(date.year, date.month, date.day);
    return day.isBefore(today)
        ? const Err(TaskError.pastDue)
        : Ok(TaskEditModel(title: title, dueDate: date));
  }
}

/// Domain error implementing formularium's [ILocalizable] — one rendering path
/// for field errors and domain errors.
enum TaskError implements ILocalizable {
  pastDue,
  saveFailed;

  @override
  String localize() => switch (this) {
        TaskError.pastDue => 'The due date cannot be in the past.',
        TaskError.saveFailed => 'Could not save the task. Try again.',
      };
}
